mapper.insert:
insert into goodscollection.goods(goodsId, goodsSeries, ipId, brandId
, size
, price
, type
,craft
,dateTime
,isLink
,isSecond)
values(#{goodsId}, #{goodsSeries}, #{ipId}, #{brandId}
, #{size}
, #{price}
, #{type}
, #{craft}
, #{dateTime}
,#{isLink}
,#{isSecond})

mapper.update:
update goodscollection.goods
goodsSeries=#{goodsSeries}, ipId=#{ipId}, size=#{size}, price=${price}, type=#{type}, craft=#{craft}, dateTime=#{dateTime}, isLink=#{isLink}, isSecond=#{isSecond}, brandId=#{brandId}
where goodsId=#{goodsId}

mapper.select:
select *
from goodscollection.goods
where ipId=#{ipId} and dateTime=#{dateTime}

select distinct goods.*
from goodscollection.goods
inner join goodscollection.ip on goods.ipId = ip.ipId
inner join goodscollection.productassociations on goods.goodsId = productassociations.goodsId
inner join goodscollection.persona on productassociations.personaId = persona.personaId
inner join goodscollection.brand on goods.brandId = brand.brandId
where ipName REGEXP #{text}
   OR goodsSeries REGEXP #{text}
   OR personaName REGEXP #{text}
   OR brandName REGEXP #{text}
